import{_ as t,a as r,b as s,c as o,d as a,e as i,f as n,g as l,h as p,i as m,j as u,k as c,l as d,m as h,n as _,o as f,p as g,q as v,r as x,s as y,t as z,u as b,v as q,w as D,x as S,y as P,z as k,A as L,B as w,C,D as T,E as A,F as W,G as V,H as j,I as F,J as I,K as N,L as E,M as G,N as U,O as B,P as $,Q as K,R as M,S as O,T as X}from"./chunks/M-S-SW-AW-ST13.BF6FVufy.js";import{_ as R}from"./chunks/M-S-SW-AW-3DM.DGzdotDO.js";import{_ as J,o as H,c as Q,a3 as Y}from"./chunks/framework.g9mfNVRQ.js";const pe=JSON.parse(`{"title":"Utiliser l'extension Wear","description":"","frontmatter":{"source_hash":"f17272d683","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/smartwatch/usewear.md","filePath":"fr/smartwatch/usewear.md"}`),Z={name:"fr/smartwatch/usewear.md"};function ee(te,e,re,se,oe,ae){return H(),Q("div",null,[...e[0]||(e[0]=[Y('<p>Vous trouverez la documentation de référence <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">ici</a>.</p><h2 id="discover-wear-extension" tabindex="-1">Découvrir l&#39;extension Wear <a class="header-anchor" href="#discover-wear-extension" aria-label="Permalink to &quot;Découvrir l&#39;extension Wear {#discover-wear-extension}&quot;">​</a></h2><p>xDrip propose quatre cadrans natifs.</p><table tabindex="0"><thead><tr><th style="text-align:center;">XDrip</th><th style="text-align:center;">XDrip(BigChart)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+t+'" style="zoom:75%;"></td><td style="text-align:center;"><img src="'+r+'" style="zoom:75%;"></td></tr><tr><td style="text-align:center;"><strong>XDrip(Large)</strong></td><td style="text-align:center;"><strong>XDrip(Circle)</strong></td></tr><tr><td style="text-align:center;"><img src="'+s+'" style="zoom:75%;"></td><td style="text-align:center;"><img src="'+o+'" style="zoom:75%;"></td></tr></tbody></table><p>Les cadrans avec graphique ont plusieurs éléments en commun avec l&#39;écran principal de xDrip.</p><ol><li>La dernière glycémie mesurée.<br> L&#39;écart de glycémie avec la valeur précédente reçue.<br> La tendance par rapport à la mesure précédente.</li><li>Une ligne d&#39;état.</li><li>Un graphique de glycémie.</li></ol><img src="'+a+'" style="zoom:75%;"><p>Un double appui sur le graphique change l&#39;échelle de temps.</p><img src="'+i+'" style="zoom:75%;"><p>Comme l&#39;extension Wear de xDrip contient une partie du code de l&#39;application, vous trouverez des éléments de menu de xDrip sur la montre. Ils se trouvent dans les applications de la montre, et certains sont aussi accessibles depuis le graphique de la montre via le menu à trois points présent sur tous les cadrans.</p><img src="'+R+'" style="zoom:75%;"><h3 id="xdrip-prefs" tabindex="-1">xDrip Prefs. <a class="header-anchor" href="#xdrip-prefs" aria-label="Permalink to &quot;xDrip Prefs. {#xdrip-prefs}&quot;">​</a></h3><p>Ce menu contient les options d&#39;affichage de votre cadran.<br> Lorsque la montre est configurée en collecteur autonome, d&#39;autres éléments sont visibles. Voir ci-dessous.</p><img src="'+n+'" style="zoom:75%;"><p>Le thème sombre affiche un fond noir avec un texte et un graphique blancs. S&#39;il est désactivé, c&#39;est l&#39;inverse : fond blanc avec texte et graphique foncés.</p><img src="'+l+'" style="zoom:75%;"><p>Refresh on change met à jour le cadran à chaque changement de données (toutes les 5 minutes au minimum). Si vous le désactivez, la montre mettra à jour son cadran toutes les minutes (ce qui consomme plus de batterie).</p><img src="'+p+'" style="zoom:75%;"><p>Show treatment ajoute des points de traitement sur les cadrans avec graphique.</p><img src="'+m+'" style="zoom:75%;"><p>Le format 24 heures force l&#39;affichage de l&#39;heure dans ce format.</p><img src="'+u+'" style="zoom:75%;"><p>Show date affiche aussi la date sur le cadran.</p><img src="'+c+'" style="zoom:75%;"><p>Si votre montre est configurée pour utiliser ses propres paramètres régionaux (langue), vous pouvez la forcer à utiliser ceux du téléphone.</p><img src="'+d+'" style="zoom:75%;"><p>Les toasts sont des messages contextuels : vous pouvez les activer et obtenir des informations supplémentaires en appuyant sur les pas et l&#39;état sur la montre.</p><img src="'+h+'" style="zoom:75%;"><p>Si votre montre le permet et que vous avez autorisé xDrip Prefs. à accéder aux données des capteurs de la montre, le podomètre s&#39;affichera sur le cadran et vous pourrez afficher les <a href="./../use/display.html">données de pas</a> dans xDrip sur votre téléphone.</p><img src="'+_+'" style="zoom:75%;"><p>Si votre montre le permet et que vous avez autorisé xDrip Prefs. à accéder aux données des capteurs de la montre, la fréquence cardiaque s&#39;affichera sur le cadran et vous pourrez afficher les <a href="./../use/display.html">données de fréquence cardiaque</a> dans xDrip sur votre téléphone.</p><img src="'+f+'" style="zoom:75%;"><p>Si vous utilisez un système de boucle fermée open source (comme AAPS) qui diffuse des données vers xDrip, vous pouvez ajouter l&#39;état de la boucle à la ligne d&#39;état.</p><img src="'+g+'" style="zoom:75%;"><p>Par défaut, le cadran affiche la batterie de l&#39;appareil collecteur sous la forme <code>uploader</code> ou <code>wear</code>. Il s&#39;agit d&#39;une ancienne définition qui n&#39;apporte rien si vous n&#39;utilisez pas xDrip comme téléphone principal : elle n&#39;affichera ni le niveau de batterie du téléphone principal ni celui d&#39;un éventuel transmetteur, mais uniquement la batterie de votre téléphone et de votre montre.</p><img src="'+v+'" style="zoom:75%;"><p>Permet d&#39;afficher les cartes (alertes) avec un fond uni pour améliorer la lisibilité.</p><img src="'+x+'" style="zoom:75%;"><p>Vous pouvez changer la taille de police de la ligne d&#39;état : 10 ou 12 points.</p><img src="'+y+'" style="zoom:75%;"><p>Vous pouvez changer la plage de temps du graphique, comme avec un double appui dessus.</p><img src="'+z+'" style="zoom:75%;"><p>Ce menu contient les personnalisations du cadran circulaire.</p><img src="'+b+'" style="zoom:75%;"><p>Couleur basse.</p><img src="'+q+'" style="zoom:75%;"><p>Sur xDrip et xDrip Large, change la couleur du séparateur (ligne d&#39;état) pour l&#39;assortir au fond.</p><img src="'+D+'" style="zoom:75%;"><p>Force update est disponible sur les montres Wear 2.0 et supérieures, s&#39;il est proposé pour la version actuelle et activé comme expliqué <a href="./wearinstall.html#wear-os-2x-and-3x">ici</a>.</p><img src="'+S+'" style="zoom:75%;"><p>Demigod est disponible pour les <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">montres modifiées</a>.</p><img src="'+P+'" style="zoom:75%;"><h3 id="keypad-treatment" tabindex="-1">Keypad Treatment <a class="header-anchor" href="#keypad-treatment" aria-label="Permalink to &quot;Keypad Treatment {#keypad-treatment}&quot;">​</a></h3><p>Keypad Treatment est identique à l&#39;<a href="./../use/mainUI.html#treatments">icône seringue</a> de xDrip.</p><img src="'+k+'" style="zoom:75%;"><img src="'+L+'" style="zoom:75%;"><h3 id="spoken-treatment" tabindex="-1">Spoken treatment <a class="header-anchor" href="#spoken-treatment" aria-label="Permalink to &quot;Spoken treatment {#spoken-treatment}&quot;">​</a></h3><p>Spoken treatment (traitement vocal) fonctionne comme dans xDrip.</p><img src="'+w+'" style="zoom:75%;"><img src="'+C+'" style="zoom:75%;"><h3 id="snooze-alert" tabindex="-1">Snooze Alert <a class="header-anchor" href="#snooze-alert" aria-label="Permalink to &quot;Snooze Alert {#snooze-alert}&quot;">​</a></h3><p>Toutes les alertes et alarmes ne sont pas disponibles sur la montre.</p><img src="'+T+'" style="zoom:75%;"><p>Sur Wear 1.x, les alarmes et alertes qui renvoient vers le téléphone doivent être mises en veille depuis l&#39;application xDrip du téléphone.</p><img src="'+A+'" style="zoom:75%;"><p>Sur Wear 2.x et supérieur, les alertes peuvent s&#39;afficher sous forme de notifications : vous devrez alors ouvrir manuellement l&#39;écran Mise en veille Alertes du téléphone ou les mettre en veille depuis l&#39;application xDrip du téléphone.</p><img src="'+W+'" style="zoom:75%;"><h2 id="standalone-collector-mode" tabindex="-1"><a href="./wear.html#standalone-collector-mode">Mode collecteur autonome</a> <a class="header-anchor" href="#standalone-collector-mode" aria-label="Permalink to &quot;[Mode collecteur autonome](./wear#standalone-collector-mode) {#standalone-collector-mode}&quot;">​</a></h2><p>Le menu xDrip Prefs. contient des informations supplémentaires reprises de xDrip sur le téléphone lorsque les deux sont connectés.</p><h4 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation {#validation}&quot;">​</a></h4><p>Un mécanisme de validation garantit que les deux utilisent les mêmes paramètres. Si la montre n&#39;accepte pas un changement de paramètres venant de xDrip, ceux-ci seront automatiquement modifiés pour correspondre aux paramètres de la montre lorsque les deux seront connectés.</p><ol><li>Les paramètres sont modifiés sur le téléphone</li><li>Les modifications sont envoyées à la montre, lorsqu&#39;elle est connectée</li><li>La montre essaie d&#39;appliquer les modifications de paramètres</li><li>Les paramètres de la montre sont renvoyés au téléphone (modifiés ou non)</li><li>Les paramètres du téléphone sont mis à jour pour refléter ceux de la montre, lorsqu&#39;elle est connectée</li></ol><img src="'+V+'" style="zoom:75%;"><p>Cela fonctionne aussi dans l&#39;autre sens. Si les paramètres de la montre sont modifiés, ils seront envoyés au téléphone lors de la connexion. xDrip sur le téléphone validera les modifications et les renverra à la montre en guise de confirmation.</p><ol><li>Les paramètres sont modifiés sur la montre</li><li>Les modifications sont envoyées au téléphone, lorsqu&#39;il est connecté</li><li>xDrip sur le téléphone valide les modifications de paramètres</li><li>Les paramètres du téléphone sont renvoyés à la montre (validés ou non)</li><li>Les paramètres de la montre sont mis à jour pour refléter ceux du téléphone, lorsqu&#39;il est connecté</li></ol><img src="'+j+'" style="zoom:75%;"><h4 id="xdrip-prefs-1" tabindex="-1">xDrip Prefs. <a class="header-anchor" href="#xdrip-prefs-1" aria-label="Permalink to &quot;xDrip Prefs. {#xdrip-prefs-1}&quot;">​</a></h4><p>Lorsque le collecteur autonome est activé, des entrées supplémentaires apparaissent dans le menu.</p><p>BT collector indique quel collecteur de source de données matérielle est configuré dans xDrip sur votre téléphone.</p><img src="'+F+'" style="zoom:75%;"><p>Enable collector correspond au paramètre de <a href="./wear.html#standalone-collector-mode">Intégration Wear OS</a>.</p><img src="'+I+'" style="zoom:75%;"><p>De même pour Force collector. Si la montre n&#39;est pas connectée au téléphone et que vous avez perdu la connexion avec votre capteur, vous pouvez l&#39;utiliser pour forcer une tentative de reconnexion.</p><img src="'+N+'" style="zoom:75%;"><p>En mode collecteur autonome, vous pouvez utiliser (certaines) alertes locales de la montre. Elles seront mises en veille sur la montre.</p><img src="'+E+'" style="zoom:75%;"><p>Y compris l&#39;alerte haute persistante.</p><img src="'+G+'" style="zoom:75%;"><p>Si votre montre a un haut-parleur, elle peut aussi faire sonner les alarmes.</p><img src="'+U+'" style="zoom:75%;"><p>Si vous vous connectez à un G5 ou un G6, vous trouverez des paramètres supplémentaires.</p><img src="'+B+'" style="zoom:75%;"><p>Ce sont des copies des paramètres du téléphone Paramètres de débogage Dexcom - Old G5 Collector Settings.</p><img src="'+$+'" style="zoom:75%;"><img src="'+K+'" style="zoom:75%;"><img src="'+M+'" style="zoom:75%;"><img src="'+O+'" style="zoom:75%;"><p>Force screen on garantit que la montre sera complètement réveillée pendant la recherche.</p><img src="'+X+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',101)])])}const me=J(Z,[["render",ee]]);export{pe as __pageData,me as default};
